// Pi — official pixel-art wordmark off its near-black tile.
function PiMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox="165 165 470 470"
      aria-hidden="true"
      className={className}
      fill="currentColor"
    >
      <path
        fillRule="evenodd"
        d="M165.29 165.29H517.36V400H400V517.36H282.65V634.72H165.29ZM282.65 282.65V400H400V282.65Z"
      />
      <path d="M517.36 400H634.72V634.72H517.36Z" />
    </svg>
  );
}

// OpenCode — official pixel "O" mark from the anomalyco/opencode brand assets.
// Upstream draws it as two greys; the same light/dark relationship survives as
// two opacities of one colour, which is what keeps a solid mark from shouting
// over the outline glyphs beside it.
function OpenCodeMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={className} fill="currentColor">
      <path fillOpacity="0.5" d="M18 3H6V18H18V3ZM24 24H0V0H24V24Z" />
      <path d="M18 18H6V6H18V18Z" />
    </svg>
  );
}

export interface HeroProvider {
  name: string;
  Mark: (props: { className?: string }) => React.ReactElement;
  /**
   * Optical size. No two vendors agree on how much of the icon box their glyph
   * should fill, so one shared size lets a dense mark shout while an airy one
   * (Claude) recedes. These are tuned by eye so every mark
   * carries the same weight; the 24px default covers the ones already sitting
   * right.
   */
  size?: string;
}

/**
 * The providers shown in the hero, ordered by how widely the tool is
 * recognised. The runtime catalog is much longer — see `/docs/providers` — so
 * this list stays short enough to read as one row on a laptop.
 */
export const HERO_PROVIDERS: HeroProvider[] = [
  { name: "Claude Code", Mark: ClaudeCodeMark, size: "size-[26px]" },
  { name: "Codex", Mark: CodexMark },
  { name: "OpenCode", Mark: OpenCodeMark, size: "size-[21px]" },
  { name: "Pi", Mark: PiMark, size: "size-[22px]" },
  { name: "DeepSeek Harness", Mark: DeepSeekMark, size: "size-[25px]" },
];
